import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BIMNh-ez.js";var i=JSON.parse(`{"title":"Data-driven content","description":"","frontmatter":{"title":"Data-driven content","group":"Documents","category":"Guides","head":[["meta",{"property":"og:title","content":"Data-driven content"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/data-driven/"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/data-driven/"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/data-driven/README.md"}},"headers":[],"relativePath":"data-driven/index.md","filePath":"data-driven/index.md","lastUpdated":1794204769000}`),a={name:`data-driven/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="data-driven-content" tabindex="-1">Data-driven content <a class="header-anchor" href="#data-driven-content" aria-label="Permalink to “Data-driven content”">​</a></h1><p>JSPrismarine has moved from hardcoded block, item and entity classes to a server whose content is built at runtime from data. Blocks, items, entities, recipes, loot, trading, spawning, biomes and world generation come from packs and generated tables, assembled through a small set of composable parts on every server that starts. The design is laid out in <a href="/JSPrismarine/pr-preview/pr-2948/plans/data-driven-vanilla.html">the data-driven vanilla plan</a>; these pages explain the system for people who have not read the plan or the research behind it.</p><h2 id="the-format-decision-in-one-paragraph" tabindex="-1">The format decision in one paragraph <a class="header-anchor" href="#the-format-decision-in-one-paragraph" aria-label="Permalink to “The format decision in one paragraph”">​</a></h2><p>The runtime model and every identifier are Bedrock-shaped: Bedrock names, Bedrock block states, the Bedrock palette, and the runtime ids this server already writes. Java Edition is the gameplay data source wherever Mojang publishes it as data (loot, recipes, advancements, tags, enchantments, item components, world generation) and, since Java 26.1 ships unobfuscated, also the source for the block properties and entity stats no Mojang report carries. Both pack formats load: Bedrock behavior packs define content a Bedrock client can render, and Java datapacks configure it. A generated mapping table, built from GeyserMC&#39;s MIT tables, joins the two editions in one place.</p><h2 id="the-parity-claim" tabindex="-1">The parity claim <a class="header-anchor" href="#the-parity-claim" aria-label="Permalink to “The parity claim”">​</a></h2><p>The project does not claim 1:1 Java parity. The adopted wording, from <a href="/JSPrismarine/pr-preview/pr-2948/research/edition-behavior-differences.html">the edition differences research note</a> (section 14):</p><blockquote><p>JSPrismarine implements Java Edition&#39;s gameplay rules for every behavior a server decides, verified against Java Edition&#39;s own implementation, and presents them through the Bedrock client&#39;s model of the world. Where a Java rule has no Bedrock presentation, or where the Bedrock client decides the outcome locally, the server implements the behavior the client expects.</p></blockquote><p>The note classifies 278 behavior differences between the editions and enumerates the excluded categories; <a href="/JSPrismarine/pr-preview/pr-2948/data-driven/parity.html">parity.md</a> explains how the claim is tested.</p><h2 id="reading-map" tabindex="-1">Reading map <a class="header-anchor" href="#reading-map" aria-label="Permalink to “Reading map”">​</a></h2><ul><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/architecture.html">architecture.md</a>: the pack stack, definitions and registries, the Java to Bedrock seam, where each subsystem lives, and what exists today versus what is planned.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/data-pipeline.html">data-pipeline.md</a>: the five stages that turn pinned Mojang and GeyserMC publications into committed goldens and generated tables, with the real commands.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/using-packs.html">using-packs.md</a>: loading Bedrock packs and Java datapacks with <code>@jsprismarine/packs</code>, precedence rules, and diagnostics.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/molang.html">molang.md</a>: the <code>@jsprismarine/molang</code> expression engine that Bedrock pack definitions use, with its versioned precedence rules.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/mapping.html">mapping.md</a>: the <code>@jsprismarine/mapping</code> seam between the editions, its four lookup functions, the generated tables and the reviewed loss list.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/parity.html">parity.md</a>: the <code>@jsprismarine/parity</code> test suite and dashboard that measure the claim above against committed reference data.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/gameplay-data.html">gameplay-data.md</a>: the loot, recipes, advancements, enchantments, predicates and tags the server runs out of Java&#39;s data, how a datapack replaces any of them, and what will not take effect.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/entities.html">entities.md</a>: how a Bedrock entity definition becomes a running mob, what its components, events, filters, goals and brains do here, and what a custom mob will and will not manage.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/block-properties.html">block-properties.md</a>: the per-state block property table dumped from the Java 26.3 jar and how the server reads it.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/structures.html">structures.md</a>: which of Java&#39;s 52 structures the overworld generates, how placement and piece writing are split, and where the generation differs from Java.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/dimensions.html">dimensions.md</a>: dimension types, level stems and world presets, the <code>worlds.&lt;name&gt;</code> config shape and its migration, the generator kinds, custom dimensions, portals and the client&#39;s dimension change, with the questions a real client has yet to answer.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/end-fight.html">end-fight.md</a>: End dragon combat, the exit portal and credits, four-crystal respawn, and the server-side light values used by gameplay rules.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/engine-systems.html">engine-systems.md</a>: the systems with no data form in either edition, which are redstone, fluids, fire, explosions, light and random ticking, with what each one simulates, what a tick of it costs, and where it stops.</li><li><a href="/JSPrismarine/pr-preview/pr-2948/data-driven/commands.html">commands.md</a>: which commands the server registers and which it deliberately leaves out, what Bedrock&#39;s flat command tree costs <code>/execute</code>, the scoreboard, and running <code>.mcfunction</code> files from a datapack.</li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};